insert into reviewer_private.curated_skills(id,kit)
select item->>'id', item from jsonb_array_elements($kits$[{"id":"civil-rights","title":"Constitutional rights in public life","lesson":"Identify whose action is being restricted, the protected interest, and any exception in the relevant section of Article III.","example":"An office proposes a religious qualification for exercising a political right. Article III, Section 5 expressly rules out that kind of test.","rows":[["Which article contains the Bill of Rights?","Article III","Article VI",0,"Article III contains the Bill of Rights. Article VI establishes the legislative branch."],["Which provision addresses taking privately owned land for a public facility?","Article III, Section 9 on public use and compensation","Article III, Section 10 on contracts",0,"Section 9 concerns government taking of private property for public use and requires just compensation."],["Residents wish to gather peacefully to petition a council. Which listed right directly concerns their planned action?","Peaceable assembly and petition","Protection against impairment of contracts",0,"Section 4 protects peaceable assembly and petition. Contract impairment addresses a different government action."],["Under Article III, Section 7, which reading of access to official records is accurate?","Access is absolute for every document.","Access on matters of public concern is subject to limitations set by law.",1,"Section 7 recognizes access while expressly allowing legal limitations. The absolute reading omits that qualification."],["A proposal conditions exercise of a political right on belonging to a particular religion. Which textual protection rules out that condition?","The rule on just compensation in Section 9","The prohibition on religious tests in Section 5",1,"Section 5 specifically bars tests of religion for civil or political rights. Compensation addresses government taking of property."],["A case asks about the permitted grounds for a legal restriction on travel. Which list matches Article III, Section 6?","National security, public safety, or public health, as provided by law","Administrative convenience or routine workload",0,"Section 6 lists those three grounds and ties them to law. Office convenience is absent from the provision."]]},{"id":"public-ethics","title":"Public service ethics under RA 6713","lesson":"Match the specific conduct to the governing principle. Section 4 sets conduct standards for public officials and employees. Section 5 lists specified duties.","example":"Choosing how to use an office vehicle involves public interest. An official should use public resources for public work and avoid spending them for personal convenience.","rows":[["Under Section 4, which interest should take priority in official work?","Public interest","Personal interest of the official",0,"Section 4 places public interest first. Personal benefit does not direct the use of official powers."],["Which practice fits the professionalism standard?","Offering routine patronage as part of a public role","Checking the accuracy of official work and discouraging undue patronage",1,"Section 4 links professionalism to skill and excellence and calls on personnel to discourage the perception that they dispense undue patronage."],["Which expectation relates to simple living under Section 4?","A lifestyle measured by an official’s authority to spend public funds","A lifestyle appropriate to position and income",1,"Simple living concerns a modest lifestyle appropriate to position and income. Public spending authority does not determine personal means."],["A resident asks how to submit a public-service request. Which practice aligns with the responsiveness standard in Section 4?","Explain the procedure clearly, subject to applicable limits.","Keep the procedure obscure even when it may be shared.",0,"Section 4 supports clear procedures and openness, subject to legal and public-interest qualifications. Obscurity creates needless barriers."],["An official proposes diverting fuel budgeted for inspections to a private event. Which standard directly addresses the use of that fuel?","Commitment to public interest and economical use of resources","The rule for choosing an office address",0,"The fuel is a public resource. Section 4 requires honest, economical use in the public interest. The choice of address is irrelevant."],["Under the general public-letter response duty stated in RA 6713 Section 5(a), which reply meets the stated duration and content requirements?","An acknowledgment sent within 15 working days without stating the action taken","A reply within 15 working days of receipt that states the action taken",1,"Section 5(a) gives a 15-working-day period from receipt and requires the reply to state the action taken. A bare acknowledgment omits the latter requirement."]]}]$kits$::jsonb) item
on conflict (id) do nothing;

insert into reviewer_private.concept_test_items(skill,prompt,options,correct,explanation) values
 ('civil-rights','A citizen seeks government research data used to develop a policy on a matter of public concern. Which statement reflects Article III, Section 7?',
  '["The right to information is recognized, and access is subject to limitations provided by law.","Research data is automatically excluded from the constitutional provision."]',0,
  'Section 7 includes government research data used as a basis for policy development. It also recognizes limits provided by law, so the facts alone do not determine that every item must be disclosed.'),
 ('public-ethics','Under the public-letter duty in RA 6713 Section 5(a), an office sends a timely reply saying only “We received your request.” What is missing?',
  '["A promise that every request will be granted","A statement of the action taken on the request"]',1,
  'Section 5(a) requires a response within the stated period and specifies that it contain the action taken. The provision does not require granting every request.');
